 private static final class Samples extends net.minecraft.client.gui.screens.Screen {
  private int frames;
  Samples(){super(net.minecraft.network.chat.Component.literal("Door inventory models"));}
  @Override public void render(net.minecraft.client.gui.GuiGraphics g,int mouseX,int mouseY,float partial){g.fill(0,0,width,height,0xFF0A1018);g.drawString(Minecraft.getInstance().font,"Door inventory models: source selector and content UVs",12,12,0xFFFFFFFF,false);int columns=Math.max(1,(width-24)/26);for(int i=0;i<samples.size();i++){int x=12+(i%columns)*26,y=36+(i/columns)*28;g.fill(x,y,x+18,y+18,0xFF264057);g.renderItem(samples.get(i),x+1,y+1);}g.flush();if(stage==3&&++frames>=5){var report=new JsonObject();report.addProperty("columns",columns);var models=new JsonArray();for(var item:samples)models.add(((NativeDoorItemModel.Selected)Minecraft.getInstance().getItemRenderer().getModel(item,null,null,0)).modelId());report.add("models",models);try{Files.createDirectories(Minecraft.getInstance().gameDirectory.toPath().resolve("screenshots"));Files.writeString(Minecraft.getInstance().gameDirectory.toPath().resolve("screenshots/door-item-icons-report.json"),new Gson().toJson(report));}catch(java.io.IOException error){throw new IllegalStateException(error);}stage=4;captureRequested=true;}}
 }
